using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CityApprovedTransitionCheck{
static CityApprovedTransitionCheck(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityApprovedTransition.request"))return;File.Delete("CityApprovedTransition.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/ApprovedTransition.txt",e.ToString());Debug.LogException(e);}}
static void Require(bool b,string m){if(!b)throw new Exception(m);}
static void Run(){var scene=SceneManager.GetActiveScene();var roots=scene.GetRootGameObjects();var c=roots.SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).Single();int count=roots.Sum(x=>x.GetComponentsInChildren<Light>(true).Length);var d=c.presets.day;var n=c.presets.night;Require(!ShaderUtil.ShaderHasError(n.skybox.shader),"Sky shader error");Require(d.skybox!=n.skybox,"Original day sky must remain intact");c.transitionSeconds=5;c.Apply(false);var originalIntensity=c.sun.intensity;var originalRotation=c.sun.transform.rotation;var flare=c.sunFlares.OfType<LensFlareComponentSRP>().First();float fi=flare.intensity;Require(flare.enabled&&fi>0,"Original flare missing");c.ApplyNight();Require(c.IsTransitioning,"Night button did not transition");float previous=0;for(int i=0;i<100;i++){c.AdvanceTransition(.05f);Require(c.NightBlend>=previous,"Non-monotonic night transition");previous=c.NightBlend;}c.AdvanceTransition(.1f);Require(!c.IsTransitioning&&c.IsNight&&c.NightBlend==1,"Night endpoint failed");Require(!flare.enabled,"Flare visible at night");c.ApplyDay();Require(c.IsTransitioning,"Day button did not transition");c.AdvanceTransition(2);float at=c.NightBlend;var intensity=c.sun.intensity;var sky=RenderSettings.skybox;var fog=RenderSettings.fogColor;c.ApplyNight();Require(Mathf.Abs(c.NightBlend-at)<.00001f&&Mathf.Abs(c.sun.intensity-intensity)<.00001f&&RenderSettings.skybox==sky&&RenderSettings.fogColor==fog,"Midway reversal jumped");c.AdvanceTransition(.1f);Require(c.NightBlend>at,"Reversal direction failed");c.ApplyDay();c.AdvanceTransition(6);Require(c.NightBlend==0&&!c.IsTransitioning&&!c.IsNight,"Day endpoint failed");Require(RenderSettings.skybox==d.skybox&&Mathf.Abs(c.sun.intensity-originalIntensity)<.00001f&&Quaternion.Angle(c.sun.transform.rotation,originalRotation)<.001f,"Day lighting changed");Require(flare.enabled&&Mathf.Abs(flare.intensity-fi)<.00001f,"Flare settings not restored");
int ui=0;foreach(var button in roots.SelectMany(x=>x.GetComponentsInChildren<Button>(true)))for(int i=0;i<button.onClick.GetPersistentEventCount();i++)if(button.onClick.GetPersistentTarget(i)==c&&(button.onClick.GetPersistentMethodName(i)=="ApplyDay"||button.onClick.GetPersistentMethodName(i)=="ApplyNight"))ui++;Require(ui>=2,"Button wiring missing");
Capture(scene,"Approved-Day",new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f));c.PreviewBlend(.00001f);Capture(scene,"Approved-Day-BlendCheck",new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f));c.PreviewBlend(.5f);Capture(scene,"Approved-Dusk",new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f));c.Apply(true);Capture(scene,"Approved-Night",new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f));c.Apply(false);
Require(roots.Sum(x=>x.GetComponentsInChildren<Light>(true).Length)==count,"Light count changed");EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/ApprovedTransition.txt","SUCCESS: Five-second bidirectional Day/Dusk/Night transition. 100 forward samples, reverse direction and midway reversal without jump verified. Exact original day sun, sky and flare restored at day endpoint. Original day/night presets unchanged. UI events="+ui+". Lights unchanged="+count+"; existing four-light pool. No added texture or material assets. No reflection capture per transition frame. Scene saved in original Day lighting.");}
static void Capture(Scene s,string name,Vector3 p,Vector3 target){var go=new GameObject("Transition verification"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,s);var cam=go.AddComponent<Camera>();cam.enabled=false;cam.farClipPlane=5000;cam.fieldOfView=62;cam.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));cam.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=RenderTexture.GetTemporary(1400,1000,24);var old=RenderTexture.active;try{cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/NaturalDayNight/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;cam.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
}

